public final class MainActivity extends androidx.activity.ComponentActivity {
 private static final int INK=0xFF203B32,MUTED=0xFF6A766E,CREAM=0xFFF5F1E8,GREEN=0xFF315D50;
 private LinearLayout root,content;private TextView status,evaluation,roomLabel;private MoveList moves;private ChessBoard board;private EngineService engine;
 private GameModel local=new GameModel(),online=new GameModel(),review=new GameModel(),arena=new GameModel();private int tab=-1,human=0,rating=1200,whiteRating=1200,blackRating=1200,reviewPly=0;private boolean arenaRunning=false;
 private boolean flipped=false,busy=false,resumed=false,polling=false;private String engineInfo="",analysisInfo="Select a position and tap Analyse.";
 private final Handler handler=new Handler(Looper.getMainLooper());private RoomClient rooms;private JSONObject room,state;private long roomEpoch=0;
 private final Runnable poll=()->pollRoom();
 private final Runnable arenaTick=()->think();
 private final Map<Integer,String> scores=new HashMap<>();
 private final Map<Integer,String> insights=new HashMap<>();
 @Override public void onCreate(Bundle saved){super.onCreate(saved);engine=EngineService.get(this);rooms=new RoomClient();restore();build();getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){@Override public void handleOnBackPressed(){if(tab!=-1)changeTab(-1);else finish();}});handleInvite(getIntent());}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleInvite(intent);}
 @Override protected void onResume(){super.onResume();resumed=true;if(tab==3)renderContent();else render();think();schedulePoll(0);}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);handler.removeCallbacks(arenaTick);arenaRunning=false;engine.cancel();busy=false;save();super.onPause();}
 @Override protected void onDestroy(){roomEpoch++;rooms.close();super.onDestroy();}
 private void restore(){android.content.SharedPreferences p=getSharedPreferences("games",MODE_PRIVATE);human=p.getInt("human",0);rating=p.getInt("rating",1200);whiteRating=p.getInt("whiteRating",1200);blackRating=p.getInt("blackRating",1200);try{arena=GameIO.fromMoves(p.getString("arena",""));}catch(Exception ignored){arena=new GameModel();}try{local=GameIO.fromMoves(p.getString("local",""));int resigned=p.getInt("resigned",-1);if(resigned>=0)local.resign(resigned);}catch(Exception ignored){local=new GameModel();}
  try{String r=p.getString("room",null),s=p.getString("state",null);if(r!=null)room=new JSONObject(r);if(s!=null){state=new JSONObject(s);online=fromState(state);}}catch(Exception ignored){room=null;state=null;}
  try{review=GameIO.fromMoves(p.getString("review",GameIO.moves(local)));reviewPly=review.size();}catch(Exception ignored){review=new GameModel();}
 }
 private void save(){int resigned=local.result()!=null&&local.result().endsWith("resignation")?human:-1;getSharedPreferences("games",MODE_PRIVATE).edit().putString("local",GameIO.moves(local)).putInt("human",human).putInt("rating",rating).putInt("whiteRating",whiteRating).putInt("blackRating",blackRating).putString("arena",GameIO.moves(arena)).putInt("resigned",resigned).putString("room",room==null?null:room.toString()).putString("state",state==null?null:state.toString()).putString("review",GameIO.moves(review)).apply();}
 private int dp(float x){return (int)(getResources().getDisplayMetrics().density*x+.5f);}
 private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
 private LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.HORIZONTAL);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));t.setPadding(0,dp(5),0,dp(5));return t;}
 private GradientDrawable background(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(INK);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(6),0,dp(6),0);b.setBackground(background(0xFFE5EADF,10));b.setOnClickListener(v->action.run());return b;}
 private void addButtons(String[] labels,Runnable[] actions){LinearLayout r=row();for(int i=0;i<labels.length;i++){Button b=button(labels[i],actions[i]);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(44),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));r.addView(b,lp);}content.addView(r);}
 private void build(){root=column();root.setBackgroundColor(CREAM);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
  LinearLayout header=row();header.setPadding(dp(20),dp(12),dp(20),dp(4));TextView name=text("KingFischer",26,INK,true);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button home=button("Home",()->changeTab(-1));header.addView(home,new LinearLayout.LayoutParams(dp(62),dp(36)));Button about=button("About",this::about);header.addView(about,new LinearLayout.LayoutParams(dp(70),dp(36)));root.addView(header);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();content.setPadding(dp(16),dp(6),dp(16),dp(16));android.widget.FrameLayout frame=new android.widget.FrameLayout(this);android.widget.FrameLayout.LayoutParams clp=new android.widget.FrameLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(580)),-2,Gravity.CENTER_HORIZONTAL);frame.addView(content,clp);scroll.addView(frame);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout tabs=row();String[] labels={"Home","Play","Friend","Analyse"};int[] targets={-1,0,1,2};for(int i=0;i<4;i++){final int target=targets[i];Button b=button(labels[i],()->changeTab(target));b.setTextColor(tab==target?Color.WHITE:INK);b.setBackground(background(tab==target?GREEN:CREAM,10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(52),1);lp.setMargins(dp(4),dp(5),dp(4),dp(8));tabs.addView(b,lp);}root.addView(tabs);setContentView(root);root.requestApplyInsets();renderContent();}
 private void changeTab(int value){engine.cancel();handler.removeCallbacks(arenaTick);arenaRunning=false;busy=false;if(value==2&&tab!=2&&tab!=-1){review=GameIO.fromMoves(GameIO.moves(game()));reviewPly=review.size();scores.clear();insights.clear();analysisInfo="Select a position and tap Analyse.";}tab=value;build();think();schedulePoll(0);}
 private GameModel game(){return tab==1?online:tab==2?review:tab==3?arena:local;}
 private void renderContent(){content.removeAllViews();board=null;status=null;moves=null;evaluation=null;roomLabel=null;if(tab==-1){homeScreen();return;}String subtitle=tab==0?"Your engine. Your next move.":tab==1?"A private board for two.":tab==3?"Your engine, on both sides.":"Find the moves that mattered.";content.addView(text(subtitle,15,MUTED,false));
  if(tab==1){roomLabel=text(room==null?"Create a room, then share the invitation.":"Room "+room.optString("id")+" · you play "+(room.optInt("color")==0?"White":"Black"),13,MUTED,false);content.addView(roomLabel);
   addButtons(room==null?new String[]{"Create room","Join invitation"}:new String[]{"Invite friend","Leave room"},room==null?new Runnable[]{this::createRoom,this::joinDialog}:new Runnable[]{this::inviteFriend,this::leaveRoom});}
  if(tab==2){addButtons(new String[]{"Import PGN","Share PGN","Share analysis"},new Runnable[]{this::importPgn,this::sharePgn,this::shareAnalysis});}
  status=text("",18,INK,true);content.addView(status);
  board=new ChessBoard(this);content.addView(board,new LinearLayout.LayoutParams(-1,-2));
  moves=new MoveList(this);LinearLayout.LayoutParams mlp=new LinearLayout.LayoutParams(-1,dp(154));mlp.setMargins(0,dp(12),0,dp(8));content.addView(moves,mlp);
  if(tab==0){addButtons(new String[]{"New game","Undo","Flip"},new Runnable[]{this::newGame,()->{engine.cancel();busy=false;local.undoTurn(human);save();render();think();},()->{flipped=!flipped;render();}});addButtons(new String[]{"Share PGN","Resign"},new Runnable[]{this::sharePgn,this::resign});content.addView(text("Engine rating: "+rating+" · approximate difficulty",12,MUTED,false));}
  else if(tab==1){addButtons(new String[]{"Flip","Share PGN","Resign"},new Runnable[]{()->{flipped=!flipped;render();},this::sharePgn,this::resign});content.addView(text("Untimed casual chess · moves sync while this screen is open",12,MUTED,false));}
  else if(tab==3){content.addView(text("White "+whiteRating+"  ·  Black "+blackRating+"  ·  approximate ratings",13,MUTED,false));addButtons(new String[]{arenaRunning?"Pause":"Start / resume","New match","Flip"},new Runnable[]{this::toggleArena,()->settings(true),()->{flipped=!flipped;render();}});addButtons(new String[]{"Share PGN","Analyse match"},new Runnable[]{this::sharePgn,()->changeTab(2)});}
  else {
   addButtons(new String[]{"|‹","Previous","Next","›|"},new Runnable[]{()->navigate(0),()->navigate(reviewPly-1),()->navigate(reviewPly+1),()->navigate(review.size())});
   SeekBar seek=new SeekBar(this);seek.setMax(review.size());seek.setProgress(reviewPly);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){reviewPly=p;engine.cancel();busy=false;render();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});content.addView(seek);
   addButtons(new String[]{"Analyse position","Analyse game","Stop"},new Runnable[]{()->analyse(false),()->analyse(true),()->{engine.cancel();busy=false;analysisInfo="Analysis stopped. Completed scores are kept.";render();}});
   evaluation=text("",14,INK,false);evaluation.setPadding(dp(12),dp(12),dp(12),dp(12));evaluation.setBackground(background(0xFFE5EADF,12));content.addView(evaluation);
  }
  render();
 }
 private void render(){if(board==null)return;GameModel g=game();Position p=tab==2?g.at(reviewPly):g.position();String result=tab==1?remoteResult():g.result();
  String side=p.side==0?"White":"Black";
  String message=tab==3?(result!=null?result:arenaRunning?"KingFischer "+(p.side==0?whiteRating:blackRating)+" is thinking…":"Engine match paused"):tab==2?"Position "+reviewPly+" of "+g.size():result!=null?result:tab==1?(room==null?"Ready to invite":state==null||!state.optBoolean("joined")?"Waiting for your friend…":p.side==room.optInt("color")?"Your move · "+side:side+" to move"):busy?"KingFischer is thinking…":p.side==human?"Your move · "+side:"KingFischer to move";
  if(p.inCheck()&&result==null)message+=" · check";status.setText(message);
  boolean canMove=tab==0?!busy&&p.side==human&&result==null:tab==1&&room!=null&&state!=null&&state.optBoolean("joined")&&p.side==room.optInt("color")&&!busy&&result==null;
  int ply=tab==2?reviewPly:g.size();int last=ply>0?g.move(ply-1):0;boolean flip=flipped^(tab==0?human==1:tab==1&&room!=null&&room.optInt("color")==1);
  board.set(p,flip,last,canMove,this::chooseMove);
  moves.show(g,ply,tab==2?this::navigate:null);
  if(tab==2&&evaluation!=null)evaluation.setText(scores.containsKey(reviewPly)?"White’s evaluation: "+scores.get(reviewPly)+"\n\n"+(busy?analysisInfo:insights.getOrDefault(reviewPly,analysisInfo)):analysisInfo);
 }
 private void chooseMove(int[] candidates){if(candidates.length==1){play(candidates[0]);return;}String[] names=new String[candidates.length];for(int i=0;i<names.length;i++)names[i]=switch(Move.promotion(candidates[i])){case 5->"Queen";case 4->"Rook";case 3->"Bishop";default->"Knight";};new AlertDialog.Builder(this).setTitle("Promote pawn").setItems(names,(d,i)->play(candidates[i])).show();}
 private void play(int move){if(tab==0){try{local.play(move);save();render();think();}catch(Exception e){error(e.getMessage());}}
  else if(tab==1&&room!=null&&!busy){busy=true;render();try{JSONObject body=new JSONObject().put("ply",online.size()).put("move",Move.uci(move));roomCall("/move",body,response->{busy=false;applyState(response);},message->{busy=false;error(message);schedulePoll(0);render();});}catch(JSONException e){busy=false;error(e.getMessage());}}
 }
 private void think(){if(!resumed||busy||!(tab==0||tab==3))return;GameModel active=tab==3?arena:local;if(active.result()!=null){arenaRunning=false;if(tab==3)renderContent();return;}if(tab==0&&active.position().side==human||tab==3&&!arenaRunning)return;
  busy=true;render();int chosenRating=tab==3?(active.position().side==0?whiteRating:blackRating):rating;final int sourceTab=tab;
  engine.play(active.position(),chosenRating,result->{busy=false;if(result.bestMove()!=0){try{active.play(result.bestMove());save();}catch(Exception e){arenaRunning=false;error(e.getMessage());}}if(sourceTab==3){if(active.result()!=null)arenaRunning=false;renderContent();if(arenaRunning&&resumed&&tab==3)handler.postDelayed(arenaTick,500);}else render();},line->{engineInfo=line;if(line.startsWith("Loading")&&status!=null)status.setText(line);},message->{busy=false;arenaRunning=false;render();error("Engine could not finish: "+message);});
 }
 private void newGame(){settings(false);}
 private void toggleArena(){if(arenaRunning){arenaRunning=false;engine.cancel();handler.removeCallbacks(arenaTick);busy=false;renderContent();}else if(arena.result()!=null)settings(true);else{arenaRunning=true;renderContent();think();}}
 private EditText ratingField(String label,int value,LinearLayout form){form.addView(text(label,14,INK,true));EditText field=new EditText(this);field.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);field.setSingleLine(true);field.setText(Integer.toString(value));form.addView(field);return field;}
 private void settings(boolean engines){LinearLayout form=column();form.setPadding(dp(22),dp(10),dp(22),dp(8));EditText first=ratingField(engines?"White engine rating":"Engine rating",engines?whiteRating:rating,form);EditText second=engines?ratingField("Black engine rating",blackRating,form):null;
  Spinner colour=new Spinner(this);if(!engines){form.addView(text("Your pieces",14,INK,true));colour.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"White","Black"}));colour.setSelection(human);form.addView(colour);}
  form.addView(text("400–3000. These are approximate difficulty labels, not measured Elo ratings.",12,MUTED,false));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(engines?"Engine versus engine":"Play against KingFischer").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Start game",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(vv->{try{int a=Difficulty.check(Integer.parseInt(first.getText().toString()));int b=engines?Difficulty.check(Integer.parseInt(second.getText().toString())):0;
   Runnable start=()->{engine.cancel();handler.removeCallbacks(arenaTick);busy=false;flipped=false;if(engines){whiteRating=a;blackRating=b;arena=new GameModel();tab=3;arenaRunning=true;}else{rating=a;human=colour.getSelectedItemPosition();local=new GameModel();tab=0;arenaRunning=false;}save();build();think();};dialog.dismiss();GameModel previous=engines?arena:local;if(previous.size()>0&&previous.result()==null)confirm("Start a new game?","This replaces the current "+(engines?"engine match":"engine game")+". Share its PGN first if you want to keep it.",start);else start.run();
  }catch(Exception e){first.setError("Enter ratings between 400 and 3000.");}}));dialog.show();
 }
 private void homeScreen(){content.addView(text("Make your next move.",30,INK,true));content.addView(text("Play, watch and learn with KingFischer.",16,MUTED,false));homeCard("Play the engine","Choose a rating such as 1200, and play White or Black.",()->settings(false));if(local.size()>0)homeCard("Continue your game","Resume your saved game against the "+rating+" engine.",()->changeTab(0));homeCard("Play a friend","Send a private invitation through WhatsApp or Discord.",()->changeTab(1));homeCard("Engine versus engine","Set a rating for White and Black, then watch the match.",()->{changeTab(3);if(arena.size()==0)settings(true);});homeCard("Analyse a game","Import PGN, review moves and find the engine’s suggestions.",()->changeTab(2));content.addView(text("Engine play and analysis work offline. Friend games use your room server.",13,MUTED,false));}
 private void homeCard(String title,String detail,Runnable action){LinearLayout card=column();card.setPadding(dp(16),dp(12),dp(16),dp(12));card.setBackground(background(0xFFE5EADF,12));card.addView(text(title,20,INK,true));card.addView(text(detail,14,MUTED,false));card.setOnClickListener(v->action.run());card.setFocusable(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(2));content.addView(card,lp);}

 private void resign(){if(tab==0&&local.result()==null)confirm("Resign game?","KingFischer will win this game.",()->{engine.cancel();busy=false;local.resign(human);save();render();});else if(tab==1&&room!=null&&remoteResult()==null)confirm("Resign game?","Your friend will win this game.",()->roomCall("/resign",new JSONObject(),this::applyState,this::error));}
 private String remoteResult(){if(state==null||state.isNull("result"))return null;String r=state.optString("result","");return r.isEmpty()?null:r;}
 private void share(String text,String title){Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,title));}
 private void sharePgn(){GameModel g=game();String white="White",black="Black",code=g.resultCode();if(tab==0){white=human==0?"You":"KingFischer";black=human==1?"You":"KingFischer";}if(tab==3){white="KingFischer "+whiteRating;black="KingFischer "+blackRating;}if(tab==1&&state!=null)code=state.optString("resultCode","*");share(GameIO.pgn(g,white,black,code),"Share chess game");}
 private void shareAnalysis(){if(scores.isEmpty()){error("Analyse a position or game first.");return;}StringBuilder report=new StringBuilder("KingFischer game analysis\nEvaluations are from White’s perspective.\n\n");for(int ply=0;ply<=review.size();ply++)if(scores.containsKey(ply))report.append("Position ").append(ply).append(ply==0?" · Start":" · After "+review.notation(ply-1)).append(": ").append(scores.get(ply)).append('\n').append(insights.getOrDefault(ply, "")).append("\n\n");report.append(GameIO.pgn(review,"White","Black",review.resultCode()));share(report.toString(),"Share game analysis");}
 private void navigate(int ply){reviewPly=Math.max(0,Math.min(review.size(),ply));engine.cancel();busy=false;analysisInfo="Select Analyse to search this position.";renderContent();}
 private void importPgn(){input("Import a game","Paste PGN or a space-separated UCI move sequence (e2e4 e7e5…).","",true,value->{try{review=GameIO.importGame(value);reviewPly=review.size();scores.clear();insights.clear();analysisInfo="Game imported. Analyse a position or the full game.";save();build();}catch(Exception e){error(e.getMessage());}});}
 private String score(SearchResult r,Position p){int sign=p.side==0?1:-1;int value=r.score()*sign;if(Math.abs(value)>31000){int mate=(32000-Math.abs(value)+1)/2;return "Mate "+(value<0?"−":"+")+mate;}return String.format(Locale.UK,"%+.2f pawns",sign*UciScore.cp(r.score(),p)/100.0);}
 private void analyse(boolean whole){engine.cancel();busy=true;analyseAt(whole?0:reviewPly,whole);}
 private void analyseAt(int ply,boolean whole){reviewPly=ply;Position snapshot=review.at(ply);analysisInfo=(whole?"Analysing game: ":"Analysing position: ")+ply+" / "+review.size();render();
  engine.search(snapshot,whole?900:2500,14,result->{scores.put(ply,score(result,snapshot));String best=result.bestMove()==0?"No legal move":com.kingfischer.engine.gui.MoveNotation.format(snapshot,result.bestMove(),false);String insight="Best move: "+best+" · depth "+result.depth()+" · "+String.format(Locale.UK,"%,d",result.nodes())+" nodes";insights.put(ply,insight);analysisInfo=insight+"\n"+(whole?"Completed "+(ply+1)+" of "+(review.size()+1)+" positions.":"Evaluation is from White’s perspective.");render();if(whole&&ply<review.size()&&resumed&&tab==2){analyseAt(ply+1,true);}else{busy=false;if(whole)analysisInfo+="\nGame analysis complete. Use Previous and Next to compare positions.";renderContent();}},line->{if(line.startsWith("Loading")){analysisInfo=line;render();}},message->{busy=false;analysisInfo="Analysis failed: "+message;render();});
 }
 private GameModel fromState(JSONObject s)throws JSONException{JSONArray m=s.getJSONArray("moves");StringBuilder out=new StringBuilder();for(int i=0;i<m.length();i++)out.append(m.getString(i)).append(' ');return GameIO.fromMoves(out.toString());}
 private void applyState(JSONObject response){try{GameModel g=fromState(response);state=response;online=g;save();render();}catch(Exception e){error("Invalid game received: "+e.getMessage());}}
 private void roomCall(String path,JSONObject body,Consumer<JSONObject> done,Consumer<String> fail){if(room==null)return;long ticket=roomEpoch;rooms.call(room.optString("server"),"/api/rooms/"+room.optString("id")+path,room.optString("token"),body,result->{if(ticket==roomEpoch&&!isDestroyed())done.accept(result);},error->{if(ticket==roomEpoch&&!isDestroyed())fail.accept(error);});}
 private void schedulePoll(long delay){handler.removeCallbacks(poll);if(resumed&&tab==1&&room!=null)handler.postDelayed(poll,delay);}
 private void pollRoom(){if(!resumed||tab!=1||room==null||polling)return;polling=true;roomCall("",null,response->{polling=false;applyState(response);schedulePoll(1400);},message->{polling=false;if(roomLabel!=null)roomLabel.setText(getString(R.string.connection_interrupted,message));schedulePoll(4000);});}
 private void createRoom(){String previous=getSharedPreferences("games",MODE_PRIVATE).getString("server","");input("Room server","Use your hosted HTTPS server, or a computer on your Wi-Fi for testing.",previous,false,value->{try{String base=RoomClient.server(value);getSharedPreferences("games",MODE_PRIVATE).edit().putString("server",base).apply();status.setText(R.string.creating_room);rooms.call(base,"/api/rooms",null,new JSONObject(),response->{try{response.put("server",base);setRoom(response);inviteFriend();}catch(Exception e){error(e.getMessage());}},this::error);}catch(Exception e){error(e.getMessage());}});}
 private void setRoom(JSONObject response){roomEpoch++;polling=false;busy=false;room=response;state=null;online=new GameModel();tab=1;save();build();schedulePoll(0);}
 private void inviteFriend(){if(room==null)return;if(state!=null&&state.optBoolean("joined")){error("Your friend has already joined. This room has two players.");return;}String link=room.optString("server")+"/invite?room="+room.optString("id")+"&invite="+room.optString("invite");share("Join me for a game of chess on KingFischer:\n"+link,"Invite a friend");}
 private void joinDialog(){input("Join a friend","Paste the invitation from WhatsApp or Discord.","",false,this::join);}
 private void handleInvite(Intent i){if(i.getData()!=null){String value=i.getData().toString();i.setData(null);handler.post(()->join(value));}}
 private void join(String link){try{JSONObject invitation=RoomClient.invite(link);String base=invitation.getString("server");confirm("Join chess room?","Connect to "+base+" and play Black?",()->{try{android.content.SharedPreferences prefs=getSharedPreferences("games",MODE_PRIVATE);String inviteId=invitation.toString();String key=prefs.getString("pendingInvite","").equals(inviteId)?prefs.getString("pendingJoinKey",""):"";if(key.isEmpty()){byte[] random=new byte[24];new java.security.SecureRandom().nextBytes(random);StringBuilder hex=new StringBuilder();for(byte b:random)hex.append(String.format(Locale.ROOT,"%02x",b&255));key=hex.toString();prefs.edit().putString("pendingInvite",inviteId).putString("pendingJoinKey",key).apply();}JSONObject body=new JSONObject().put("invite",invitation.getString("invite")).put("joinKey",key);rooms.call(base,"/api/rooms/"+invitation.optString("room")+"/join",null,body,response->{try{response.put("server",base);setRoom(response);}catch(Exception e){error(e.getMessage());}},this::error);}catch(Exception e){error(e.getMessage());}});}catch(Exception e){error(e.getMessage());}}
 private void leaveRoom(){confirm("Leave this room?","Leaving removes your saved access to this room from this phone. Share the PGN first if you want to keep the game.",()->{handler.removeCallbacks(poll);roomEpoch++;polling=false;room=null;state=null;online=new GameModel();save();build();});}
 private void input(String title,String hint,String initial,boolean multiline,Consumer<String> submit){EditText field=new EditText(this);field.setText(initial);field.setHint(hint);field.setTextSize(14);field.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(multiline?android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE:android.text.InputType.TYPE_TEXT_VARIATION_URI));field.setMinLines(multiline?5:2);field.setMaxLines(multiline?10:3);LinearLayout wrapper=column();wrapper.setPadding(dp(20),dp(10),dp(20),dp(8));wrapper.addView(field);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(wrapper).setNegativeButton("Cancel",null).setPositiveButton("Continue",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{String value=field.getText().toString().trim();if(value.isEmpty()){field.setError("Enter a value");return;}dialog.dismiss();submit.accept(value);}));dialog.show();}
 private void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,i)->yes.run()).show();}
 private void error(String message){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("KingFischer").setMessage(message==null?"Something went wrong":message).setPositiveButton("OK",null).show();}
 private void about(){new AlertDialog.Builder(this).setTitle("KingFischer Mobile · 0.2").setMessage("Native Android interface for George Miller’s KingFischer2 Java engine. Engine play and analysis use the bundled NNUE network offline.\n\nOnline rooms use a separately hosted server. No accounts, ads or purchases in this first chess build.\n\nGPL-3.0-or-later. Contains work derived from the Stockfish developers; full notices and corresponding source are included with the project. Chess-piece artwork is reproduced from your desktop project.\n\nCasual games automatically end at threefold repetition or 50 moves without a pawn move or capture. Rating labels control search effort and occasional alternatives. They are approximate difficulty settings, not calibrated Elo ratings.").setPositiveButton("OK",null).show();}
}
